-- ============================================================
-- VitalCore: food_database Schema & Data Seed
-- ============================================================

CREATE TABLE IF NOT EXISTS public.food_database (
  id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  food_name    TEXT        NOT NULL,
  serving_size TEXT        DEFAULT '100g',
  calories     NUMERIC     NOT NULL DEFAULT 0,
  protein_g    NUMERIC     DEFAULT 0,
  carbs_g      NUMERIC     DEFAULT 0,
  fat_g        NUMERIC     DEFAULT 0,
  fiber_g      NUMERIC     DEFAULT 0,
  sugar_g      NUMERIC     DEFAULT 0,
  sodium_mg    NUMERIC     DEFAULT 0,
  category     TEXT        DEFAULT 'General',
  source       TEXT        DEFAULT 'dataset',
  created_at   TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.food_database ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone authenticated can read food database" ON public.food_database;
CREATE POLICY "Anyone authenticated can read food database"
  ON public.food_database FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Anyone authenticated can insert food database" ON public.food_database;
CREATE POLICY "Anyone authenticated can insert food database"
  ON public.food_database FOR INSERT TO authenticated WITH CHECK (true);

CREATE INDEX IF NOT EXISTS idx_food_name ON public.food_database(food_name);
CREATE INDEX IF NOT EXISTS idx_food_category ON public.food_database(category);











